jsonTools.init:
function init(eli) {
  // ELI Agent: Revise Document and Address Comments, its plan, review and apply engine (tools/eli_agent parts 12, 20,
  // 40, 50, 55, 65b, 71, 75, 75h, 76, 77, 78) in a bundle of its own (docs/ELI_AGENT_SPLIT_PLAN.md step 5). ELI Agent,
  // the host, hands over what it uses (H): the run, its screens and areas, and the shared helpers below, by name. Beside
  // an ELI Agent that doesn't hand over every one of them (one that still holds Revise itself: an older one, or one
  // reverted to it) this bundle does nothing.
  var H = typeof eli.dispatch === "function" ? eli.dispatch("eli_agent", "host") : null;
  // A newer ELI Agent started in this session (an update installed while ELI was open): this bundle starts again
  // beside it, and this copy stops listening. Listened for even while it does nothing, so a host that arrives later
  // gets it too.
  var reattach = eli.bus && typeof eli.bus.on === "function" ? eli.bus.on("eli_agent:host", function (e) {
    if (!e || !e.host || e.host === H) return;
    if (typeof reattach === "function") reattach();
    init(eli);
  }) : null;
  if (!H || !(H.apiVersion >= 1) || !H.fn) return;
  var RE_REDLINE_MARK = H.fn.RE_REDLINE_MARK, _aiJsonCall = H.fn._aiJsonCall, _bodyHeader = H.fn._bodyHeader,
    _cleanView = H.fn._cleanView, _closeAgentOverlay = H.fn._closeAgentOverlay, _dtMatch = H.fn._dtMatch,
    _egArea = H.fn._egArea, _egNorm = H.fn._egNorm, _egRun = H.fn._egRun, _egScreen = H.fn._egScreen,
    _egSides = H.fn._egSides, _egStartArea = H.fn._egStartArea, _esc = H.fn._esc, _findAgent = H.fn._findAgent,
    _flat = H.fn._flat, _getAgentSettings = H.fn._getAgentSettings, _guidanceBlock = H.fn._guidanceBlock,
    _loadPlaybookSnippets = H.fn._loadPlaybookSnippets, _markupView = H.fn._markupView, _readRow = H.fn._readRow,
    _readText = H.fn._readText, _redlineAuthors = H.fn._redlineAuthors,
    _relabelExecutionBlock = H.fn._relabelExecutionBlock, _renderOverlayBody = H.fn._renderOverlayBody,
    _renderStream = H.fn._renderStream, _reviewed = H.fn._reviewed, _runPlaybookPass = H.fn._runPlaybookPass,
    _scrollIntoView = H.fn._scrollIntoView, _scrollSoon = H.fn._scrollSoon, _stageStrip = H.fn._stageStrip,
    _stream = H.fn._stream, _truncate = H.fn._truncate, _wireCancelOnly = H.fn._wireCancelOnly;
  if ([RE_REDLINE_MARK, _aiJsonCall, _bodyHeader, _cleanView, _closeAgentOverlay, _dtMatch, _egArea, _egNorm, _egRun,
    _egScreen, _egSides, _egStartArea, _esc, _findAgent, _flat, _getAgentSettings, _guidanceBlock,
    _loadPlaybookSnippets, _markupView, _readRow, _readText, _redlineAuthors, _relabelExecutionBlock,
    _renderOverlayBody, _renderStream, _reviewed, _runPlaybookPass, _scrollIntoView, _scrollSoon, _stageStrip,
    _stream, _truncate, _wireCancelOnly].indexOf(undefined) >= 0) return;

  function _bodyApplying() {
    var run = _egRun(), L = run && run.applyLive;
    if (!L) return _bodyHeader() + '<div class="_eg_status_box"><div class="_eg_status_dot"></div><div>Applying redlines to the document…</div></div>';
    return _bodyHeader() +
      '<div class="_eg_status_box"><div class="_eg_status_dot"></div><div id="_rv_whead">' + _esc(_rvWriteHead(L)) + '</div></div>' +
      '<div class="_td_wl" id="_rv_wl">' + _rvWriteRows(run) + '</div>';
  }
  // ─── [RV-WRITE] ───────────────────────────────────────────────────
  // Applying, as it happens (the owner's rule: a step at work is never a bare spinner — 24 renames took 10-18 s, a
  // shortened section 38-44 s, behind "Applying redlines…"). Every accepted edit in the order Word writes them, each a
  // digest (where · Change / Add / Remove; the words struck → written; why); the one Word is writing marked, ✓ as each
  // lands, ⚠ and the reason when one doesn't; a counter and the clock; then "Reading it back…" while the written clauses
  // are checked. Respond's writing-stream look (the host's stylesheet), painted in place so the list never jumps.
  var RV_WRITE_ACT = { replace: ["Change", "Changed"], insert: ["Add", "Added"], "delete": ["Remove", "Removed"], sigblock: ["Add", "Added"], definition: ["Add", "Added"] };
  function _rvWriteStart(accepted) {
    var run = _egRun();
    if (!run) return;
    run.applyLive = { t0: Date.now(), ids: accepted.map(function (e) { return e.id; }), st: {}, why: {}, phase: "write" };
    accepted.forEach(function (e) { run.applyLive.st[e.id] = "wait"; });
    if (!run._rvTick) run._rvTick = setInterval(function () {
      if (!_egRun() || _egRun() !== run || run.status !== "applying") { clearInterval(run._rvTick); run._rvTick = null; return; }
      var h = document.getElementById("_rv_whead");
      if (h) h.textContent = _rvWriteHead(run.applyLive);
    }, 1000);
  }
  function _rvWriteMark(id, st, why) {
    var L = _egRun() && _egRun().applyLive;
    if (!L || !(id in L.st)) return;
    L.st[id] = st;
    if (why) L.why[id] = why;
    _rvWritePaint(id);
  }
  function _rvWritePhase(phase) { var L = _egRun() && _egRun().applyLive; if (!L) return; L.phase = phase; _rvWritePaint(); }
  function _rvWriteHead(L) {
    var n = L.ids.length, done = L.ids.filter(function (id) { return L.st[id] === "done" || L.st[id] === "warn"; }).length;
    var s = Math.max(0, Math.floor((Date.now() - L.t0) / 1000)), clock = Math.floor(s / 60) + ":" + ("0" + s % 60).slice(-2);
    return (L.phase === "check" ? "Reading the written clauses back · " + done + " of " + n + " written" : "Writing " + Math.min(done + 1, n) + " of " + n + " into Word") + " · " + clock;
  }
  function _rvWriteLineHtml(e, st, why) {
    var a = RV_WRITE_ACT[e.type] || RV_WRITE_ACT.replace, past = st === "done" || st === "warn";
    var ic = st === "done" ? "✓" : st === "warn" ? "⚠" : st === "cur" ? '<span class="_td_spin"></span>' : "";
    var was = _egNorm(e._anchoredText || e.anchorText || ""), now = _egNorm(e.replacementText || ""), change;
    if (e.type === "insert" || e.type === "sigblock" || e.type === "definition") change = '<ins class="_td_ins">' + _esc(_truncate(now, 140)) + '</ins>';
    else if (e.type === "delete") change = '<del class="_td_del">' + _esc(_truncate(was, 140)) + '</del>';
    else {
      // Only the words that change, with three either side: "…and Supplier → O'Reilly have entered…".
      var A = was.split(" "), B = now.split(" "), i = 0, j = 0;
      while (i < A.length && i < B.length && A[i] === B[i]) i++;
      while (j < A.length - i && j < B.length - i && A[A.length - 1 - j] === B[B.length - 1 - j]) j++;
      var pre = A.slice(Math.max(0, i - 3), i).join(" "), post = B.slice(B.length - j, B.length - j + 3).join(" ");
      var del = A.slice(i, A.length - j).join(" "), ins = B.slice(i, B.length - j).join(" ");
      change = (i > 3 ? "…" : "") + _esc(pre) + (pre ? " " : "") + (del ? '<del class="_td_del">' + _esc(_truncate(del, 90)) + '</del>' : "") + (del && ins ? " → " : "") +
        (ins ? '<ins class="_td_ins">' + _esc(_truncate(ins, 90)) + '</ins>' : "") + (post ? " " + _esc(post) : "") + (j > 3 ? "…" : "");
    }
    return '<div class="_td_wl_line _td_wl_' + st + '" data-rv-wl="' + _esc(e.id) + '">' +
      '<span class="_td_wl_ic">' + ic + '</span><div class="_td_wl_main"><div class="_td_wl_top"><span class="_td_wl_sec">' + _esc(e.section || e.paragraphId || "") + '</span>' +
      '<span class="_td_wl_act _td_wl_act_' + (st === "warn" ? "miss" : past ? "accept" : "counter") + '">' + _esc(st === "warn" ? "Not applied" : past ? a[1] : st === "cur" ? "Writing…" : a[0]) + '</span></div>' +
      '<div class="_td_wl_sum">' + change + '</div>' + (why ? '<div class="_td_wl_why">' + _esc(_truncate(why, 160)) + '</div>' : "") + '</div></div>';
  }
  function _rvWriteRows(run) {
    var L = run.applyLive, byId = {};
    ((run.plan && run.plan.edits) || []).forEach(function (e) { byId[e.id] = e; });
    return L.ids.filter(function (id) { return byId[id]; }).map(function (id) { return _rvWriteLineHtml(byId[id], L.st[id], L.why[id] || byId[id].rationale || ""); }).join("");
  }
  // One row (or only the header) repainted where it stands; the row Word is on kept in view, a third of the way down.
  function _rvWritePaint(id) {
    var run = _egRun(), L = run && run.applyLive, wl = document.getElementById("_rv_wl"), h = document.getElementById("_rv_whead");
    if (!L || !wl) return;
    if (h) h.textContent = _rvWriteHead(L);
    if (id) {
      var e = ((run.plan && run.plan.edits) || []).filter(function (x) { return x.id === id; })[0], row = wl.querySelector('[data-rv-wl="' + id + '"]');
      if (e && row) row.outerHTML = _rvWriteLineHtml(e, L.st[id], L.why[id] || e.rationale || "");
    }
    var cur = wl.querySelector("._td_wl_cur");
    if (cur) wl.scrollTop = Math.max(0, cur.offsetTop - wl.clientHeight / 3);
  }
  // ─── [/RV-WRITE] ──────────────────────────────────────────────────
  function _bodyApplied() {
    var r = _egRun().applyResult || { applied: 0, failures: [], appliedEdits: [] };
    var appliedEdits = r.appliedEdits || [];
    // Group applied edits by section for the same orientation users
    // already learned in the review view.
    var groups = {};
    var groupOrder = [];
    appliedEdits.forEach(function (e) {
      var key = e.section || e.category || "Other";
      if (!groups[key]) { groups[key] = []; groupOrder.push(key); }
      groups[key].push(e);
    });
    var listHtml = '';
    if (appliedEdits.length) {
      listHtml = '<div class="_eg_section_label" style="margin-top:14px;">APPLIED EDITS (' + appliedEdits.length + ')</div>' +
        '<div class="_eg_prop_hint">Click any row to find it in the document.</div>' +
        groupOrder.map(function (g) {
          return '<div class="_eg_group">' +
            '<div class="_eg_group_header">' + _esc(g) + ' <span class="_eg_group_count">(' + groups[g].length + ')</span></div>' +
            groups[g].map(function (e) { return _appliedRowHtml(e); }).join("") +
          '</div>';
        }).join('');
    }
    var failHtml = "";
    if (r.failures && r.failures.length) {
      failHtml = '<div class="_eg_section_label" style="margin-top:14px;">NOT APPLIED (' + r.failures.length + ')</div>' +
        '<div class="_eg_prop_hint">These were not written to the document. ' +
        'Each one shows what it would have changed, so you can make it by hand.</div>' +
        r.failures.map(function (f) {
          return _failCardHtml(f);
        }).join("");
    }
    var pa = _egRun().postAudit;
    var canRecheck = (_egRun().requirements || []).length && !(pa && pa.running);
    return _bodyHeader() +
      '<div class="_eg_applied_box">' +
        '<div class="_eg_applied_title">✓ Applied ' + r.applied + ' redline' + (r.applied === 1 ? "" : "s") + ' to the document.</div>' +
        '<div class="_eg_applied_sub">Word now shows them as tracked changes — accept/reject in the Review pane.</div>' +
      '</div>' +
      _commentOfferHtml(appliedEdits) +
      _renderPostAuditSection(pa) +
      listHtml +
      failHtml +
      // At the BOTTOM of the revisions, not above them: you read what went
      // into the document, then what is left for you. Entering this screen
      // scrolls here, so the list is behind you by the time you arrive.
      _renderFollowUpSection(
        (_egRun().plan && _egRun().plan.edits) || appliedEdits,
        _egRun().plan || {}) +
      '<div class="_eg_actions_row _eg_actions_sticky">' +
        '<button id="_eg_new_plan" type="button" class="_eg_btn_secondary">New Plan</button>' +
        (canRecheck
          ? '<button id="_eg_post_audit" type="button" class="_eg_btn_secondary" ' +
            'title="Re-read the document and re-check it against your request">🔍 ' +
            (pa ? 'Re-check again' : 'Check the document') + '</button>'
          : '') +
        // Email-agent only: surface the response-email generator on the applied page.
        (_egRun().agent === "address_comments"
          ? '<button id="_eg_gen_response_email" type="button" class="_eg_btn_secondary">📧 Generate response email</button>'
          : '') +
        '<button id="_eg_close_done" type="button" class="_eg_btn_primary">Done</button>' +
      '</div>';
  }
  // The re-check, on the applied screen. Same checklist as the pre-apply
  // audit, scored against the document instead of against a simulation —
  // so it reuses the same renderer.
  function _renderPostAuditSection(pa) {
    if (!pa) return "";
    if (pa.running) {
      return '<div class="_eg_audit_box">' +
        '<div class="_eg_audit_head">Re-reading the document and checking it against ' +
        'your request…</div>' +
      '</div>';
    }
    if (pa.error) {
      return '<div class="_eg_audit_box">' +
        '<div class="_eg_audit_head">⚠ Re-check did not run</div>' +
        '<div class="_eg_audit_row"><span class="_eg_audit_text">' + _esc(pa.error) +
        ' — what is in the document has NOT been checked against your request.' +
        '</span></div>' +
      '</div>';
    }
    return _renderCoverageSection(pa) +
      (pa.gaps && pa.gaps.length
        ? '<div class="_eg_actions_row" style="padding-top:0;">' +
          '<button id="_eg_fix_gaps" type="button" class="_eg_btn_primary">Plan ' +
          pa.gaps.length + ' fix' + (pa.gaps.length === 1 ? "" : "es") + ' →</button>' +
        '</div>'
        : "");
  }
  // Compact applied-edit row — section + paragraph + tiny inline-style
  // diff + Locate button. Reads as a confirmation list, not a review
  // card (these have already happened, no decisions to make).
  // "INSERT" said nothing about what was being inserted. Every insert adds a
  // whole new section now, so the badge says so.
  function _typeBadge(e) {
    var t = (e && e.type) || "replace";
    return '<span class="_eg_type_badge _eg_type_' + t + '">' +
      _esc(t === "insert" ? "NEW SECTION" : t === "sigblock" ? "SIGNATURE BLOCK" : t === "definition" ? "DEFINITION" : t.toUpperCase()) + '</span>';
  }
  function _appliedRowHtml(e) {
    var typeBadge = _typeBadge(e);
    var paraLine = "";
    if (e.paragraphIndex && e.paragraphTotal) {
      paraLine = '<span class="_eg_applied_para">¶ ' + e.paragraphIndex + '/' + e.paragraphTotal + '</span>';
    }
    var change = "";
    if (e.type === "delete") {
      change = '<del class="_eg_inline_del">' + _esc(_truncate(e.anchorText, 90)) + '</del>';
    } else if (e.type === "insert") {
      change = '<span class="_eg_applied_inserts">+ ' + _esc(_truncate(e.replacementText, 90)) + '</span>';
    } else {
      change =
        '<del class="_eg_inline_del">' + _esc(_truncate(e.anchorText, 60)) + '</del>' +
        ' <ins class="_eg_inline_ins">' + _esc(_truncate(e.replacementText, 60)) + '</ins>';
    }
    // A heading ELI wrote was restyled to match the document's others.
    // That is a formatting change the user did not ask for, so it is said
    // rather than left to be noticed.
    var hmCase = { upper: "ALL CAPS", lower: "lower case",
      title: "Title Case", sentence: "Sentence case" };
    var hm = e._headingMatched
      ? '<div class="_eg_applied_fmt">Heading matched to the document' +
        (e._headingMatched.style
          ? ' (' + _esc(e._headingMatched.style) + ')'
          : ((e._headingMatched.facets || []).length
              ? ' (' + _esc(e._headingMatched.facets.join(", ")) + ')' : "")) +
        (e._headingMatched.recased
          ? ' · recased to ' + _esc(hmCase[e._headingMatched.recased] ||
              e._headingMatched.recased) : "") +
        ((e._headingMatched.para || []).length ? ' · kept its alignment' : "") +
        '</div>'
      : "";
    // Word cannot keep two values for one facet through a replace, so a
    // sentence with a bolded term in the middle loses it. Say so — the
    // alternative is the user finding out by reading.
    var ff = (e._formattingFlattened || []).length
      ? '<div class="_eg_applied_fmt">' + (e._leadKept
          ? 'The heading “' + _esc(e._leadKept) + '” kept its formatting; any other mixed ' +
            _esc(e._formattingFlattened.join(" and ")) + ' in the clause was not carried over — re-apply it if it mattered.'
          : 'The original mixed ' + _esc(e._formattingFlattened.join(" and ")) +
            ' could not be kept through the replacement — re-apply it if it mattered.') + '</div>'
      : "";
    // The row locates, like the review cards. A button for the action you
    // take on nearly every row you read is one more thing to aim at.
    // [RESTATE] The backstop's finding: the clause now says the same words twice in a row.
    var dbl = e._doubled ? '<div class="_eg_applied_fmt">Now reads “' + _esc(_truncate(e._doubled, 80)) + '” twice in a row — check this clause.</div>' : "";
    // [KEEP-HEADING] The draft restated the heading with small changes nobody asked for.
    if (e._headingKept) dbl += '<div class="_eg_applied_fmt">Kept the heading “' + _esc(e._headingKept.was) + '” as it is — the change didn\'t call for retitling it (the draft had “' + _esc(e._headingKept.proposed) + '”).</div>';
    return '<div class="_eg_applied_row _eg_card_clickloc" data-eg-applied-id="' + _esc(e.id) + '" data-eg-applied-locate="' + _esc(e.id) + '" title="Click to find this in the document">' +
      '<div class="_eg_applied_meta">' + typeBadge + paraLine + '</div>' +
      '<div class="_eg_applied_change">' + change + '</div>' + hm + ff + dbl +
    '</div>';
  }
  // [RESTATE] The guard's backstop, after apply: a rewritten paragraph that
  // now says the same words twice in a row ("Trade Secrets. Trade Secrets.")
  // is pointed out on its applied row. Two words and six letters at least,
  // so "that that" or "(a) (a)" don't count.
  function _dupRun(text) {
    var w = String(text || "").split(/\s+/).filter(Boolean);
    for (var n = Math.min(12, Math.floor(w.length / 2)); n >= 2; n--) {
      for (var i = 0; i + 2 * n <= w.length; i++) {
        var a = w.slice(i, i + n).join(" ").toLowerCase(), b = w.slice(i + n, i + 2 * n).join(" ").toLowerCase();
        if (a === b && a.replace(/[^a-z]/g, "").length >= 6) return w.slice(i, i + n).join(" ");
      }
    }
    return null;
  }
  function _checkDoubled(edits) {
    var todo = (edits || []).filter(function (e) { return e.type !== "insert" && e.type !== "delete" && (e._spanAnchor || e.paragraphId); });
    if (!todo.length) return Promise.resolve();
    return eli.host.runRaw("eli_agent:check_doubled", function (context) {
      var doc = context.document;
      var rs = todo.map(function (e) {
        var r = doc.getBookmarkRangeOrNullObject(e._spanAnchor || e.paragraphId);
        r.load("isNullObject");
        return { e: e, r: r };
      });
      return context.sync().then(function () {
        var reads = rs.filter(function (x) { return !x.r.isNullObject; }).map(function (x) {
          var c = x.r.paragraphs.getFirst().getRange("Content");
          return { e: x.e, t: _reviewed(c, "Current"), o: _reviewed(c, "Original") };
        });
        return context.sync().then(function () {
          reads.forEach(function (x) {
            // Only what the edit made: "New York, New York" was there before it.
            var d = _dupRun(x.t.value);
            if (d && _dupRun(x.o.value) !== d) { x.e._doubled = d; _stream("warn", "Reads twice after the edit", (x.e.section || x.e.id) + ": “" + _truncate(d, 60) + "”"); }
          });
        });
      });
    });
  }
  // [COMMENT-OFFER] Once the revisions are in, offer comments explaining them —
  // all of them, or a choice. Ask ELI writes them (its comments dialog: who
  // for, review, add). Hidden when Ask ELI can't (not loaded, or a Word
  // without comments) and after "No thanks" — for these revisions; the next
  // plan's are offered again.
  // TO REMOVE: delete to [/COMMENT-OFFER] + its call in _bodyApplied and the
  // three buttons in _wireAppliedControls.
  function _commentOfferHtml(appliedEdits) {
    var can = eli.get && typeof eli.get("ask_eli", "comment_revisions") === "function";
    var r = _egRun().applyResult || {};
    if (!can || !appliedEdits.length || r.commentOffer === "no") return "";
    var n = appliedEdits.length;
    return '<div class="_eg_cmo">' +
      '<div class="_eg_cmo_k">Comments</div>' +
      '<div class="_eg_cmo_t">Add comments explaining ' + (n === 1 ? "this change" : "these " + n + " changes") + '?</div>' +
      '<div class="_eg_cmo_s">ELI writes one per revision, for your team or the other side, and you choose which go in.</div>' +
      '<div class="_eg_cmo_b">' +
        '<button id="_eg_cmo_all" type="button" class="_eg_btn_primary">' + (n === 1 ? "Add a comment" : "All " + n + " changes") + '</button>' +
        (n > 1 ? '<button id="_eg_cmo_some" type="button" class="_eg_btn_secondary">Choose which</button>' : "") +
        '<button id="_eg_cmo_no" type="button" class="_eg_cmo_no">No thanks</button>' +
      '</div>' +
    '</div>';
  }
  function _commentOfferOpen(preselect) {
    var applied = (_egRun().applyResult && _egRun().applyResult.appliedEdits) || [];
    var revisions = applied.map(function (e) {
      return {
        section: String(e.section || e.category || ""),
        type: String(e.type || "replace"),
        before: e.type === "insert" ? "" : String(e.anchorText || e._anchoredText || ""),
        after: e.type === "delete" ? "" : String(e.replacementText || ""),
        why: String(e.rationale || ""),
      };
    });
    var r = null;
    try { r = eli.dispatch("ask_eli", "comment_revisions", { revisions: revisions, preselect: preselect }); } catch (_e) { r = null; }
    if (!(r && r.ok) && typeof showToast === "function") showToast("Comments couldn't be opened here.", "info");
  }
  // ─── [/COMMENT-OFFER] ─────────────────────────────────────────────
  function _wireAppliedControls(body) {
    var cmoAll = body.querySelector("#_eg_cmo_all");     // [COMMENT-OFFER]
    if (cmoAll) cmoAll.onclick = function () { _commentOfferOpen("all"); };
    var cmoSome = body.querySelector("#_eg_cmo_some");
    if (cmoSome) cmoSome.onclick = function () { _commentOfferOpen("some"); };
    var cmoNo = body.querySelector("#_eg_cmo_no");
    if (cmoNo) cmoNo.onclick = function () {
      if (_egRun().applyResult) _egRun().applyResult.commentOffer = "no";
      _renderOverlayBody();
    };
    var nb = body.querySelector("#_eg_new_plan");
    if (nb) nb.onclick = function () {
      _egRun().plan = null;
      _egRun().acceptance = {};
      _egRun().editOverrides = {};
      _egRun().applyResult = null;
      _egRun().status = "capturing";
      _renderOverlayBody();
      _runPlan();
    };
    var cb = body.querySelector("#_eg_close_done");
    if (cb) cb.onclick = _closeAgentOverlay;
    var pab = body.querySelector("#_eg_post_audit");
    if (pab) pab.onclick = function () { _runPostApplyAudit(); };
    var fixb = body.querySelector("#_eg_fix_gaps");
    if (fixb) fixb.onclick = function () { _planPostAuditFixes(); };
    // Per-row Locate button — same _locateEdit path the review cards use.
    // A failed edit still knows where it was MEANT to go. Locating falls
    // back to the paragraph when the anchor itself is gone, which is the
