        (it.sev ? '<span class="_eg_fu_dot"></span>' : '') +
        (it.where ? '<span class="_eg_fu_where">' + _esc(it.where) + '</span>' : '') +
        '<span class="_eg_fu_what">' + _esc(it.what) +
          (it.detail ? '<span class="_eg_fu_detail">' + _esc(it.detail) + '</span>' : '') +
        '</span>' +
      '</div>';
    };
    var capped = function (list) {
      return list.slice(0, 20).map(row).join("") +
        (list.length > 20 ? '<div class="_eg_fu_row"><span class="_eg_fu_what">' +
          (list.length - 20) + ' more — see the panels above.</span></div>' : '');
